import java.math.BigInteger;

public class Dh {
    public static void main(String[] args) {
        BigInteger p = BigInteger.valueOf(23);
        BigInteger g = BigInteger.valueOf(5);
        BigInteger a = BigInteger.valueOf(6);   // Alice private
        BigInteger b = BigInteger.valueOf(15);  // Bob private
        BigInteger A = g.modPow(a, p);
        BigInteger B = g.modPow(b, p);
        System.out.println("public p=" + p + " g=" + g);
        System.out.println("Alice sends A = g^a mod p = 5^6 mod 23 = " + A);
        System.out.println("Bob sends   B = g^b mod p = 5^15 mod 23 = " + B);
        System.out.println("Alice computes B^a mod p = " + B.modPow(a, p));
        System.out.println("Bob computes   A^b mod p = " + A.modPow(b, p));
        for (int x = 1; x < 23; x++) {
            if (g.modPow(BigInteger.valueOf(x), p).equals(A)) {
                System.out.println("Eavesdropper finds a=" + x
                        + " by exhaustive search (22 tries at most)");
                break;
            }
        }
    }
}

