import java.nio.charset.StandardCharsets;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.MessageDigest;
import java.security.Signature;
import javax.crypto.KeyAgreement;

public class Sg {
    public static void main(String[] args) throws Exception {
        KeyPairGenerator kpg = KeyPairGenerator.getInstance("RSA");
        kpg.initialize(2048);
        KeyPair kp = kpg.generateKeyPair();
        byte[] m = "hello".getBytes(StandardCharsets.UTF_8);
        Signature s = Signature.getInstance("SHA256withRSA");
        s.initSign(kp.getPrivate());
        s.update(m);
        byte[] sig = s.sign();
        System.out.println("signature length bytes = " + sig.length);
        s.initVerify(kp.getPublic());
        s.update(m);
        System.out.println("verify original = " + s.verify(sig));
        s.initVerify(kp.getPublic());
        s.update("hellp".getBytes(StandardCharsets.UTF_8));
        System.out.println("verify altered  = " + s.verify(sig));

        KeyPairGenerator ec = KeyPairGenerator.getInstance("X25519");
        KeyPair a = ec.generateKeyPair();
        KeyPair b = ec.generateKeyPair();
        KeyAgreement ka = KeyAgreement.getInstance("X25519");
        ka.init(a.getPrivate());
        ka.doPhase(b.getPublic(), true);
        byte[] s1 = ka.generateSecret();
        KeyAgreement kb = KeyAgreement.getInstance("X25519");
        kb.init(b.getPrivate());
        kb.doPhase(a.getPublic(), true);
        byte[] s2 = kb.generateSecret();
        System.out.println("X25519 secrets equal = " + MessageDigest.isEqual(s1, s2)
                + ", length " + s1.length);
    }
}

import java.nio.charset.StandardCharsets;
import java.util.HexFormat;
import javax.crypto.Cipher;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;

public class Nonce {
    static byte[] enc(byte[] key, byte[] iv, String msg) throws Exception {
        Cipher c = Cipher.getInstance("AES/GCM/NoPadding");
        c.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(key, "AES"), new GCMParameterSpec(128, iv));
        return c.doFinal(msg.getBytes(StandardCharsets.UTF_8));
    }

    public static void main(String[] args) throws Exception {
        byte[] key = new byte[16];
        for (int i = 0; i < 16; i++) key[i] = (byte) (i * 7 + 1);
        byte[] iv = new byte[12];       // the same 96-bit nonce used twice: a protocol bug
        String m1 = "transfer 100 to acct 42";
        String m2 = "transfer 900 to acct 77";
        byte[] c1 = enc(key, iv, m1), c2 = enc(key, iv, m2);
        System.out.println("c1 = " + HexFormat.of().formatHex(c1, 0, m1.length()));
        System.out.println("c2 = " + HexFormat.of().formatHex(c2, 0, m2.length()));
        StringBuilder x = new StringBuilder();
        for (int i = 0; i < m1.length(); i++) {
            int cx = (c1[i] ^ c2[i]) & 0xFF, px = (m1.charAt(i) ^ m2.charAt(i)) & 0xFF;
            if (cx != px) throw new IllegalStateException("mismatch at " + i);
            x.append(String.format("%02x", cx));
        }
        System.out.println("c1 xor c2 = " + x);
        System.out.println("m1 xor m2 equals c1 xor c2 for all " + m1.length()
                + " bytes: the key stream cancelled");
    }
}

import com.sun.net.httpserver.HttpsConfigurator;
import com.sun.net.httpserver.HttpsServer;
import java.io.FileInputStream;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.security.KeyStore;
import javax.net.ssl.KeyManagerFactory;
import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManagerFactory;

public class TlsDemo {
    static SSLContext context(String keyStoreFile, String trustStoreFile) throws Exception {
        char[] pw = "changeit".toCharArray();
        KeyManagerFactory kmf = null;
        TrustManagerFactory tmf = null;
        if (keyStoreFile != null) {
            KeyStore ks = KeyStore.getInstance("PKCS12");
            try (var in = new FileInputStream(keyStoreFile)) { ks.load(in, pw); }
            kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
            kmf.init(ks, pw);
        }
        if (trustStoreFile != null) {
            KeyStore ts = KeyStore.getInstance("PKCS12");
            try (var in = new FileInputStream(trustStoreFile)) { ts.load(in, pw); }
            tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
            tmf.init(ts);
        }
        SSLContext c = SSLContext.getInstance("TLS");
        c.init(kmf == null ? null : kmf.getKeyManagers(),
               tmf == null ? null : tmf.getTrustManagers(), null);
        return c;
    }

    static void call(String name, SSLContext c) {
        try {
            HttpClient hc = HttpClient.newBuilder().sslContext(c).build();
            HttpRequest req = HttpRequest.newBuilder(
                    URI.create("https://localhost:8444/hi")).build();
            HttpResponse<String> r = hc.send(req, HttpResponse.BodyHandlers.ofString());
            var tls = r.sslSession().get();
            System.out.println(name + ": " + r.statusCode() + " " + r.body() + " via "
                    + tls.getProtocol() + " " + tls.getCipherSuite());
        } catch (Exception e) {
            Throwable t = e;
            while (t.getCause() != null) t = t.getCause();
            System.out.println(name + ": " + e.getClass().getSimpleName());
            System.out.println("  root cause: " + t.getClass().getName() + ": " + t.getMessage());
        }
    }

    public static void main(String[] args) throws Exception {
        HttpsServer s = HttpsServer.create(new InetSocketAddress("127.0.0.1", 8444), 0);
        s.setHttpsConfigurator(new HttpsConfigurator(context("server.p12", null)));
        s.createContext("/hi", ex -> {
            byte[] b = "hello over TLS".getBytes(StandardCharsets.UTF_8);
            ex.sendResponseHeaders(200, b.length);
            ex.getResponseBody().write(b);
            ex.close();
        });
        s.start();
        call("default truststore", SSLContext.getDefault());
        call("custom truststore ", context(null, "trust.p12"));
        s.stop(0);
    }
}

import java.nio.charset.StandardCharsets;
import java.util.Base64;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class Jwt {
    static String b64(byte[] b) {
        return Base64.getUrlEncoder().withoutPadding().encodeToString(b);
    }

    static String sign(String signingInput, String secret) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
        return b64(mac.doFinal(signingInput.getBytes(StandardCharsets.UTF_8)));
    }
    static String text(String part) {
        return new String(Base64.getUrlDecoder().decode(part), StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws Exception {
        String header = b64("{\"alg\":\"HS256\",\"typ\":\"JWT\"}".getBytes(StandardCharsets.UTF_8));
        String payload = b64(("{\"sub\":\"user-42\",\"iss\":\"https://auth.example.com\","
                + "\"iat\":1790000000,\"exp\":1790000900,\"scope\":\"orders:read\"}")
                .getBytes(StandardCharsets.UTF_8));
        String token = header + "." + payload + "."
                + sign(header + "." + payload, "demo-secret-key");
        System.out.println(token);
        String[] parts = token.split("\\.");
        System.out.println("header  = " + text(parts[0]));
        System.out.println("payload = " + text(parts[1]));
        boolean ok = sign(parts[0] + "." + parts[1], "demo-secret-key").equals(parts[2]);
        System.out.println("signature valid with correct key: " + ok);
        String tampered = b64("{\"sub\":\"admin\",\"exp\":1790000900}"
                .getBytes(StandardCharsets.UTF_8));
        System.out.println("signature valid after payload change: "
                + sign(parts[0] + "." + tampered, "demo-secret-key").equals(parts[2]));
    }
}

