public class Ssrf {
    static boolean blocked(InetAddress a) {
        return a.isLoopbackAddress() || a.isSiteLocalAddress() || a.isLinkLocalAddress()
                || a.isAnyLocalAddress() || a.isMulticastAddress();
    }

    public static void main(String[] args) throws Exception {
        for (String h : new String[] {"127.0.0.1", "10.1.2.3", "172.16.5.9", "192.168.0.10",
                "169.254.169.254", "0.0.0.0", "192.0.2.10", "203.0.113.7"}) {
            InetAddress a = InetAddress.getByName(h);
            System.out.printf("%-16s blocked=%b%n", h, blocked(a));
        }
    }
}

public class Bucket {
    final double capacity, refillPerSec;
    double tokens;
    long lastNanos;

    Bucket(double capacity, double refillPerSec, long nowNanos) {
        this.capacity = capacity;
        this.refillPerSec = refillPerSec;
        this.tokens = capacity;
        this.lastNanos = nowNanos;
    }

    boolean tryAcquire(long nowNanos) {
        tokens = Math.min(capacity, tokens + (nowNanos - lastNanos) / 1e9 * refillPerSec);
        lastNanos = nowNanos;
        if (tokens >= 1) { tokens -= 1; return true; }
        return false;
    }

    public static void main(String[] args) {
        Bucket b = new Bucket(5, 2, 0);           // burst of 5, sustained 2 requests per second
        long t = 0;
        for (int i = 0; i < 12; i++) {            // one request every 100 ms for 1.2 s
            boolean ok = b.tryAcquire(t);
            System.out.printf("t=%4d ms  %s  tokens left %.2f%n",
                    t / 1_000_000, ok ? "200 OK " : "429 Too Many", b.tokens);
            t += 100_000_000L;
        }
    }
}

import java.util.Arrays;

public class LbSim {
    // One request arrives per time unit. Every third request is heavy (9 units), the others take 1.
    static int cost(int i) { return i % 3 == 2 ? 9 : 1; }

    static void run(String name, boolean leastConn) {
        int servers = 3, n = 12;
        double[] busyUntil = new double[servers];        // one worker per server, FIFO queue
        double[] finish = new double[n];
        int[] server = new int[n];
        int[] peak = new int[servers];
        for (int i = 0; i < n; i++) {
            double t = i;
            int pick = i % servers;
            if (leastConn) {
                int best = Integer.MAX_VALUE;
                for (int s = 0; s < servers; s++) {
                    int a = 0;
                    for (int j = 0; j < i; j++) if (server[j] == s && finish[j] > t) a++;
                    if (a < best) { best = a; pick = s; }
                }
            }
            server[i] = pick;
            double start = Math.max(t, busyUntil[pick]);
            finish[i] = start + cost(i);
            busyUntil[pick] = finish[i];
            int a = 0;
            for (int j = 0; j <= i; j++) if (server[j] == pick && finish[j] > t) a++;
            peak[pick] = Math.max(peak[pick], a);
        }
        double worst = 0, sumWait = 0;
        for (int i = 0; i < n; i++) {
            worst = Math.max(worst, finish[i] - i);
            sumWait += finish[i] - i - cost(i);
        }
        System.out.printf("%s%n  server per request %s%n  peak concurrent %s, mean queueing %.2f, "
                + "slowest response %.0f%n", name, Arrays.toString(server), Arrays.toString(peak),
                sumWait / n, worst);
    }

    public static void main(String[] args) {
        run("round robin", false);
        run("least connections", true);
    }
}

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class Ring {
    static long hash(String s) throws Exception {
        byte[] d = MessageDigest.getInstance("MD5").digest(s.getBytes(StandardCharsets.UTF_8));
        long h = 0;
        for (int i = 0; i < 4; i++) h = (h << 8) | (d[i] & 0xFF);
        return h;                       // 32-bit position on the ring
    }

    static TreeMap<Long, String> build(List<String> nodes, int vnodes) throws Exception {
        TreeMap<Long, String> ring = new TreeMap<>();
        for (String n : nodes)
            for (int v = 0; v < vnodes; v++) ring.put(hash(n + "#" + v), n);
        return ring;
    }

    static String lookup(TreeMap<Long, String> ring, String key) throws Exception {
        Map.Entry<Long, String> e = ring.ceilingEntry(hash(key));
        return (e != null ? e : ring.firstEntry()).getValue();
    }

    public static void main(String[] args) throws Exception {
        List<String> nodes = List.of("10.0.1.11", "10.0.1.12", "10.0.1.13");
        TreeMap<Long, String> one = build(nodes, 1);
        System.out.println("Ring with 1 position per server:");
        one.forEach((k, v) -> System.out.printf("  %10d (%08x)  %s%n", k, k, v));
        for (String key : List.of("user-1001", "user-1002", "user-1003"))
            System.out.printf("  key %-10s hash %10d -> %s%n", key, hash(key), lookup(one, key));

        int keys = 10000;
        for (int vn : new int[] {1, 100}) {
            TreeMap<Long, String> before = build(nodes, vn);
            TreeMap<Long, String> after = build(List.of("10.0.1.11", "10.0.1.12"), vn);
            int moved = 0;
            int[] load = new int[3];
            for (int i = 0; i < keys; i++) {
                String k = "user-" + i;
                String a = lookup(before, k), b = lookup(after, k);
                load[nodes.indexOf(a)]++;
                if (!a.equals(b)) moved++;
            }
            System.out.printf("vnodes=%3d load %s, keys moved after removing .13: %d of %d%n",
                    vn, Arrays.toString(load), moved, keys);
        }
        int movedMod = 0;
        for (int i = 0; i < keys; i++) {
            long h = hash("user-" + i);
            if (h % 3 != h % 2) movedMod++;
        }
        System.out.println("hash mod N: keys moved when N changes 3 -> 2: "
                + movedMod + " of " + keys);
    }
}

import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

public class MiniLb {
    static final int[] PORTS = {9001, 9002, 9003};
    static final boolean[] healthy = {true, true, true};
    static final AtomicInteger next = new AtomicInteger();
    static final HttpClient client =
            HttpClient.newBuilder().connectTimeout(Duration.ofMillis(300)).build();

    static HttpServer backend(int port) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress("127.0.0.1", port), 0);
        s.createContext("/", ex -> {
            String xff = ex.getRequestHeaders().getFirst("X-Forwarded-For");
            String host = ex.getRequestHeaders().getFirst("Host");
            byte[] b = ("backend:" + port + " saw X-Forwarded-For=" + xff + " Host=" + host)
                    .getBytes(StandardCharsets.UTF_8);
            ex.sendResponseHeaders(200, b.length);
            ex.getResponseBody().write(b);
            ex.close();
        });
        s.start();
        return s;
    }

    static void healthCheck() {
        for (int i = 0; i < PORTS.length; i++) {
            try {
                HttpRequest probe = HttpRequest.newBuilder(
                        URI.create("http://127.0.0.1:" + PORTS[i] + "/health")).build();
                healthy[i] = client.send(probe, HttpResponse.BodyHandlers.discarding())
                        .statusCode() == 200;
            } catch (Exception e) {
                healthy[i] = false;
            }
        }
    }

    static String pick() {
        for (int tries = 0; tries < PORTS.length; tries++) {
            int i = Math.floorMod(next.getAndIncrement(), PORTS.length);
            if (healthy[i]) return "http://127.0.0.1:" + PORTS[i];
        }
        return null;
    }

    static void show(HttpClient user) throws Exception {
        for (int i = 0; i < 4; i++) {
            var r = user.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:9000/x")).build(),
                    HttpResponse.BodyHandlers.ofString());
            System.out.println(r.statusCode() + " " + r.body());
        }
    }

    public static void main(String[] args) throws Exception {
        List<HttpServer> backends = new ArrayList<>();
        for (int p : PORTS) backends.add(backend(p));
        HttpServer lb = HttpServer.create(new InetSocketAddress("127.0.0.1", 9000), 0);
        lb.createContext("/", ex -> {
            String target = pick();
            byte[] out;
            int code = 200;
            if (target == null) {
                out = "no healthy backend".getBytes(StandardCharsets.UTF_8);
                code = 503;
            } else {
                try {
                    HttpRequest rq = HttpRequest.newBuilder(URI.create(target + ex.getRequestURI()))
                            .header("X-Forwarded-For",
                                    ex.getRemoteAddress().getAddress().getHostAddress())
                            .build();
                    out = client.send(rq, HttpResponse.BodyHandlers.ofByteArray()).body();
                } catch (Exception e) {
                    out = "bad gateway".getBytes(StandardCharsets.UTF_8);
                    code = 502;
                }
            }
            ex.sendResponseHeaders(code, out.length);
            ex.getResponseBody().write(out);
            ex.close();
        });
        lb.start();

        HttpClient user = HttpClient.newHttpClient();
        System.out.println("-- round robin, all healthy");
        show(user);
        backends.get(1).stop(0);                      // backend 9002 fails
        System.out.println("-- 9002 stopped, before the health check runs");
        show(user);
        healthCheck();
        System.out.println("-- after the health check marks 9002 down");
        show(user);
        lb.stop(0);
        for (HttpServer s : backends) s.stop(0);
    }
}

