import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
public class EdgeCache {
    record Entry(byte[] body, long storedAtMs, long maxAgeSec) {}

    static final AtomicInteger originHits = new AtomicInteger();
    static final Map<String, Entry> cache = new ConcurrentHashMap<>();
    static final HttpClient http = HttpClient.newHttpClient();

    public static void main(String[] args) throws Exception {
        HttpServer origin = HttpServer.create(new InetSocketAddress("127.0.0.1", 9201), 0);
        origin.createContext("/", ex -> {
            String text = "price list v" + originHits.incrementAndGet();
            byte[] b = text.getBytes(StandardCharsets.UTF_8);
            ex.getResponseHeaders().add("Cache-Control", "public, max-age=2");
            ex.sendResponseHeaders(200, b.length);
            ex.getResponseBody().write(b);
            ex.close();
        });
        origin.start();

        HttpServer edge = HttpServer.create(new InetSocketAddress("127.0.0.1", 9200), 0);
        edge.createContext("/", ex -> {
            String key = ex.getRequestURI().toString();
            long now = System.currentTimeMillis();
            Entry e = cache.get(key);
            String state;
            if (e != null && now - e.storedAtMs() < e.maxAgeSec() * 1000) {
                state = "HIT";
            } else {
                try {
                    var req = HttpRequest.newBuilder(
                            URI.create("http://127.0.0.1:9201" + key)).build();
                    var r = http.send(req, HttpResponse.BodyHandlers.ofByteArray());
                    e = new Entry(r.body(), now, 2);
                    cache.put(key, e);
                    state = "MISS";
                } catch (Exception ex2) {
                    ex.sendResponseHeaders(502, -1);
                    ex.close();
                    return;
                }
            }
            ex.getResponseHeaders().add("X-Cache", state);
            ex.getResponseHeaders().add("Age", String.valueOf((now - e.storedAtMs()) / 1000));
            ex.sendResponseHeaders(200, e.body().length);
            ex.getResponseBody().write(e.body());
            ex.close();
        });
        edge.start();

        HttpClient user = HttpClient.newHttpClient();
        long[] pauses = {0, 1100, 600, 1000, 100};
        for (int i = 0; i < pauses.length; i++) {
            Thread.sleep(pauses[i]);
            var req = HttpRequest.newBuilder(
                    URI.create("http://127.0.0.1:9200/prices.json")).build();
            var r = user.send(req, HttpResponse.BodyHandlers.ofString());
            System.out.printf("request %d: X-Cache=%s Age=%s body=\"%s\" origin hits so far=%d%n",
                    i + 1, r.headers().firstValue("x-cache").get(),
                    r.headers().firstValue("age").get(), r.body(), originHits.get());
        }
        edge.stop(0);
        origin.stop(0);
    }
}

import java.util.Random;

public class Backoff {
    static final long BASE_MS = 100, CAP_MS = 5000;

    static long delay(int attempt, boolean jitter, Random rnd) {
        long exp = Math.min(CAP_MS, BASE_MS << attempt);       // 100, 200, 400, 800, 1600 ...
        return jitter ? (long) (rnd.nextDouble() * exp) : exp; // full jitter: uniform in [0, exp)
    }

    public static void main(String[] args) {
        Random rnd = new Random(7);
        System.out.println("attempt  plain-delay-ms  full-jitter-sample-ms");
        for (int a = 0; a < 6; a++)
            System.out.printf("%7d  %14d  %21d%n",
                    a + 1, delay(a, false, rnd), delay(a, true, rnd));

        int clients = 1000;
        for (boolean jitter : new boolean[] {false, true}) {
            int[] perBucket = new int[100];          // 50 ms buckets, third retry only
            for (int c = 0; c < clients; c++) {
                long t = 0;
                for (int a = 0; a < 3; a++) t += delay(a, jitter, rnd);
                perBucket[(int) Math.min(99, t / 50)]++;
            }
            int peak = 0, used = 0;
            for (int v : perBucket) { peak = Math.max(peak, v); if (v > 0) used++; }
            System.out.printf("%s: third retry of %d clients lands in %d distinct 50 ms windows, "
                    + "peak %d%n", jitter ? "full jitter" : "no jitter  ", clients, used, peak);
        }
        System.out.println("Layered retries: 3 attempts at each of 3 tiers = "
                + (int) Math.pow(3, 3) + " calls reach the database per user request");
    }
}

public class Breaker {
    enum State { CLOSED, OPEN, HALF_OPEN }

    State state = State.CLOSED;
    int failures = 0;
    long openedAt = 0;
    final int threshold;
    final long openMs;

    Breaker(int threshold, long openMs) { this.threshold = threshold; this.openMs = openMs; }

    // returns what happened to the call at virtual time t
    String call(long t, boolean dependencyHealthy) {
        if (state == State.OPEN) {
            if (t - openedAt < openMs) return "rejected immediately (OPEN)";
            state = State.HALF_OPEN;                       // allow one trial call
        }
        boolean probe = state == State.HALF_OPEN;
        if (dependencyHealthy) {
            state = State.CLOSED;
            failures = 0;
            return probe ? "probe succeeded, circuit CLOSED" : "success";
        }
        failures++;
        if (probe || failures >= threshold) {
            state = State.OPEN;
            openedAt = t;
            return probe ? "probe failed, circuit OPEN again"
                         : "failure " + failures + ", circuit OPEN";
        }
        return "failure " + failures + " (timeout after 2000 ms)";
    }

    public static void main(String[] args) {
        Breaker b = new Breaker(3, 2000);
        for (long t = 0; t <= 9000; t += 500) {
            boolean healthy = t < 2000 || t >= 6000;       // dependency down from 2 s to 6 s
            System.out.printf("t=%4d ms  dependency %-4s  %-9s -> %s%n", t, healthy ? "up" : "DOWN",
                    b.state, b.call(t, healthy));
        }
    }
}

import java.time.Duration;
import java.util.List;
import org.springframework.http.CacheControl;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
