import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.Arrays;
import java.util.Random;

public class Latency {
    public static void main(String[] args) throws Exception {
        Random rnd = new Random(42);
        HttpServer s = HttpServer.create(new InetSocketAddress("127.0.0.1", 8083), 0);
        s.createContext("/work", ex -> {
            try { Thread.sleep(rnd.nextInt(100) < 3 ? 120 : 5); } catch (InterruptedException e) { }
            ex.sendResponseHeaders(204, -1);
            ex.close();
        });
        s.start();
        HttpClient c = HttpClient.newHttpClient();
        HttpRequest rq = HttpRequest.newBuilder(URI.create("http://127.0.0.1:8083/work")).build();
        int n = 400;
        double[] ms = new double[n];
        for (int i = 0; i < n; i++) {
            long t0 = System.nanoTime();
            c.send(rq, HttpResponse.BodyHandlers.discarding());
            ms[i] = (System.nanoTime() - t0) / 1e6;
        }
        Arrays.sort(ms);
        double sum = 0;
        for (double v : ms) sum += v;
        System.out.printf("calls=%d mean=%.1f ms p50=%.1f ms p95=%.1f ms p99=%.1f ms max=%.1f ms%n",
                n, sum / n, ms[n / 2], ms[(int) (n * 0.95)], ms[(int) (n * 0.99)], ms[n - 1]);
        s.stop(0);
    }
}

import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.http.HttpTimeoutException;
import java.nio.charset.StandardCharsets;
import java.time.Duration;

public class Pool {
    public static void main(String[] args) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress("127.0.0.1", 8081), 0);
        s.createContext("/port", ex -> {
            String port = String.valueOf(ex.getRemoteAddress().getPort());
            byte[] b = port.getBytes(StandardCharsets.UTF_8);
            ex.sendResponseHeaders(200, b.length);
            ex.getResponseBody().write(b);
            ex.close();
        });
        s.createContext("/slow", ex -> {
            try { Thread.sleep(1500); } catch (InterruptedException e) { }
            ex.sendResponseHeaders(204, -1);
            ex.close();
        });
        s.start();
        URI portUri = URI.create("http://127.0.0.1:8081/port");
        HttpClient hc = HttpClient.newBuilder().version(HttpClient.Version.HTTP_1_1)
                .connectTimeout(Duration.ofSeconds(2)).build();
        System.out.println("One HttpClient, sequential requests (keep-alive):");
        for (int i = 0; i < 3; i++) {
            var r = hc.send(HttpRequest.newBuilder(portUri).build(),
                    HttpResponse.BodyHandlers.ofString());
            System.out.println("  request " + (i + 1) + " -> client port " + r.body());
        }
        System.out.println("A new HttpClient (and so a new connection) per request:");
        for (int i = 0; i < 3; i++) {
            var fresh = HttpClient.newBuilder().version(HttpClient.Version.HTTP_1_1).build();
            var r = fresh.send(HttpRequest.newBuilder(portUri).build(),
                    HttpResponse.BodyHandlers.ofString());
            System.out.println("  request " + (i + 1) + " -> client port " + r.body());
        }
        long t0 = System.nanoTime();
        try {
            HttpRequest slow = HttpRequest.newBuilder(URI.create("http://127.0.0.1:8081/slow"))
                    .timeout(Duration.ofMillis(500)).build();
            hc.send(slow, HttpResponse.BodyHandlers.discarding());
        } catch (HttpTimeoutException e) {
            long ms = (System.nanoTime() - t0) / 1_000_000 / 100 * 100;
            System.out.println("per-request timeout after about " + ms + " ms: "
                    + e.getClass().getSimpleName() + ": " + e.getMessage());
        }
        s.stop(0);
    }
}

import io.netty.channel.ChannelOption;
import java.time.Duration;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.client.reactive.ReactorClientHttpConnector;
import org.springframework.web.reactive.function.client.WebClient;
import reactor.netty.http.client.HttpClient;
import reactor.netty.resources.ConnectionProvider;

@Configuration
public class HttpClientConfig {
    @Bean
    WebClient inventoryClient() {
        ConnectionProvider pool = ConnectionProvider.builder("inventory")
                .maxConnections(50)                          // Little's law plus headroom
                .pendingAcquireTimeout(Duration.ofSeconds(1)) // fail fast when exhausted
                .maxIdleTime(Duration.ofSeconds(20))         // below server/balancer idle time
                .maxLifeTime(Duration.ofMinutes(10))         // rebalance across new instances
                .evictInBackground(Duration.ofSeconds(30))
                .metrics(true)
                .build();
        HttpClient http = HttpClient.create(pool)
                .option(ChannelOption.CONNECT_TIMEOUT_MILLIS, 1000)
                .responseTimeout(Duration.ofSeconds(2));
        return WebClient.builder()
                .baseUrl("http://inventory.shop.svc.cluster.local:8080")
                .clientConnector(new ReactorClientHttpConnector(http))
                .build();
    }
}
